const originalPayload = $json;

const headers = originalPayload.headers || {};

let clientIp =
  headers['x-forwarded-for'] ||
  headers['x-real-ip'] ||
  headers['cf-connecting-ip'] ||
  headers['client-ip'] ||
  headers['x-client-ip'] ||
  originalPayload.ip ||
  'unknown';

if (typeof clientIp === 'string' && clientIp.includes(',')) {
  clientIp = clientIp.split(',')[0].trim();
}

const now = new Date();
const requestDate = now.toISOString().slice(0, 10);

return [
  {
    json: {
      requestPayload: originalPayload,
      clientIp,
      requestDate,
    },
  },
];

const meta = $node["Prepare Request + Meta"].json;

const ipDoc = $node["Get IP Quota"].json;
const globalDoc = $node["Get Global Quota"].json;

const limitPerIp = 3;
const limitGlobal = 12;

let prevUsedForIpToday = 0;
let prevUsedGlobalToday = 0;

if (ipDoc && !ipDoc.error && ipDoc.usedForIpToday !== undefined) {
  const n = Number(ipDoc.usedForIpToday);
  if (!Number.isNaN(n)) {
    prevUsedForIpToday = n;
  }
}

if (globalDoc && !globalDoc.error && globalDoc.usedGlobalToday !== undefined) {
  const n = Number(globalDoc.usedGlobalToday);
  if (!Number.isNaN(n)) {
    prevUsedGlobalToday = n;
  }
}

const usedForIpToday = prevUsedForIpToday + 1;
const usedGlobalToday = prevUsedGlobalToday + 1;

const remainingForIpToday = Math.max(limitPerIp - usedForIpToday, 0);
const remainingGlobalToday = Math.max(limitGlobal - usedGlobalToday, 0);

const quotaExceededForIp = prevUsedForIpToday >= limitPerIp;
const quotaExceededGlobal = prevUsedGlobalToday >= limitGlobal;
const quotaExceeded = quotaExceededForIp || quotaExceededGlobal;

const ipQuotaDocumentId = `ip-${meta.requestDate}-${meta.clientIp}`;
const globalQuotaDocumentId = `global-${meta.requestDate}`;

return [
  {
    json: {
      ...meta, 

      limitPerIp,
      limitGlobal,

      prevUsedForIpToday,
      prevUsedGlobalToday,

      usedForIpToday,
      usedGlobalToday,

      remainingForIpToday,
      remainingGlobalToday,

      quotaExceededForIp,
      quotaExceededGlobal,
      quotaExceeded,

      ipQuotaDocumentId,
      globalQuotaDocumentId,
    },
  },
];

const {
  limitPerIp,
  limitGlobal,
  prevUsedForIpToday,
  prevUsedGlobalToday,
} = $json;

const remainingForIpToday = Math.max(limitPerIp - prevUsedForIpToday, 0);
const remainingGlobalToday = Math.max(limitGlobal - prevUsedGlobalToday, 0);

return [
  {
    json: {
      success: false,
      reason: 'QUOTA_EXCEEDED',
      quota: {
        limitPerIp,
        remainingForIpToday,
        limitGlobal,
        remainingGlobalToday,
      },
      recipes: [],
    },
  },
];

const raw = $json.output;

if (typeof raw !== 'string') {
  throw new Error('AI Agent output is not a string. Got: ' + typeof raw);
}

let cleaned = raw
  .replace(/^```json\s*/i, '')   
  .replace(/^```\s*/i, '')       
  .replace(/```$/i, '')          
  .trim();

cleaned = cleaned.replace(
  /}\s+[A-Za-z0-9_-]+(?:\s*:\s*\[\s*\])?\s+]/g,
  '}]'
);

const lastBraceIndex = cleaned.lastIndexOf('}');
if (lastBraceIndex !== -1) {
  cleaned = cleaned.slice(0, lastBraceIndex + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(
    'Failed to parse AI Agent JSON: ' + e.message + '\nRaw: ' + cleaned
  );
}

const requestMeta = $node['Prepare Request + Meta'].json;

const userIngredientsFromRequest =
  requestMeta?.requestPayload?.body?.ingredients ?? [];

function assert(condition, message) {
  if (!condition) {
    throw new Error('Invalid recipe payload from AI Agent: ' + message);
  }
}

assert(
  Array.isArray(userIngredientsFromRequest) &&
    userIngredientsFromRequest.length > 0,
  'requestPayload.body.ingredients must be a non-empty array.'
);

const userIngredientNames = new Set(
  userIngredientsFromRequest
    .filter((ing) => ing && typeof ing.name === 'string')
    .map((ing) => ing.name.trim().toLowerCase())
);

assert(
  userIngredientNames.size > 0,
  'Could not derive any valid ingredient names from requestPayload.body.ingredients.'
);

function isNonEmptyString(val) {
  return typeof val === 'string' && val.trim().length > 0;
}

function isNumber(val) {
  return typeof val === 'number' && !isNaN(val);
}

assert(parsed && typeof parsed === 'object', 'Top-level JSON is not an object.');
assert(parsed.success === true, '"success" must be true.');
assert(
  parsed.quota && typeof parsed.quota === 'object',
  '"quota" object is missing.'
);
assert(Array.isArray(parsed.recipes), '"recipes" must be an array.');
assert(
  parsed.recipes.length === 3,
  '"recipes" must contain exactly 3 recipes.'
);

parsed.recipes.forEach((recipe, recipeIndex) => {
  const prefix = `recipes[${recipeIndex}] `;

  assert(recipe && typeof recipe === 'object', prefix + 'must be an object.');
  assert(isNonEmptyString(recipe.id), prefix + '"id" must be a non-empty string.');
  assert(isNonEmptyString(recipe.title), prefix + '"title" must be a non-empty string.');
  assert(isNumber(recipe.totalMinutes), prefix + '"totalMinutes" must be a number.');
  assert(isNonEmptyString(recipe.cuisine), prefix + '"cuisine" must be a non-empty string.');
  assert(isNonEmptyString(recipe.diet), prefix + '"diet" must be a non-empty string.');

  assert(
    Array.isArray(recipe.ingredients) && recipe.ingredients.length > 0,
    prefix + '"ingredients" must be a non-empty array.'
  );

  const userIngredients = [];
  const extraIngredients = [];

  recipe.ingredients.forEach((ing, ingIndex) => {
    const ip = `${prefix}ingredients[${ingIndex}] `;

    assert(ing && typeof ing === 'object', ip + 'must be an object.');
    assert(isNonEmptyString(ing.name), ip + '"name" must be a non-empty string.');
    assert(isNumber(ing.quantity), ip + '"quantity" must be a number.');
    assert(isNonEmptyString(ing.unit), ip + '"unit" must be a non-empty string.');

    const ingNameLower = ing.name.trim().toLowerCase();
    const isFromUser = userIngredientNames.has(ingNameLower);

    ing.isFromUser = isFromUser;

    if (isFromUser) {
      userIngredients.push(ing);
    } else {
      extraIngredients.push(ing);
    }
  });

  assert(
    userIngredients.length > 0,
    prefix + 'must contain at least one ingredient with isFromUser === true.'
  );

  const trimmedExtras = extraIngredients.slice(0, 3);
  recipe.ingredients = [...userIngredients, ...trimmedExtras];

  assert(
    trimmedExtras.length <= 3,
    prefix + 'must not contain more than 3 extra ingredients (isFromUser === false).'
  );

  assert(
    Array.isArray(recipe.steps) && recipe.steps.length > 0,
    prefix + '"steps" must be a non-empty array.'
  );

  recipe.steps.forEach((step, stepIndex) => {
    const sp = `${prefix}steps[${stepIndex}] `;

    assert(step && typeof step === 'object', sp + 'must be an object.');
    assert(isNumber(step.order), sp + '"order" must be a number.');
    assert(isNonEmptyString(step.text), sp + '"text" must be a non-empty string.');
    if (step.durationMinutes !== undefined) {
      assert(
        isNumber(step.durationMinutes),
        sp + '"durationMinutes", if present, must be a number.'
      );
    }
  });
});

const quotaMeta = $node['Check & Prepare Quota'].json;

if (quotaMeta) {
  parsed.quota = {
    limitPerIp: quotaMeta.limitPerIp,
    remainingForIpToday: quotaMeta.remainingForIpToday,
    limitGlobal: quotaMeta.limitGlobal,
    remainingGlobalToday: quotaMeta.remainingGlobalToday,
  };
}

return [
  {
    json: parsed,
  },
];
